function _claimLiquidity(uint256 lpAmount_, address recipient_) internal returns (uint256 pairOut_) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    address bond_ = address(s.bondNftVault);
    address claim_ = address(s.rebasingClaimToken);
    if (msg.sender != bond_ && msg.sender != claim_ && msg.sender != address(this)) {
        revert UniswapV4SingleStandardExchangeDETFRepo.NotAuthorized(msg.sender);
    }
    if (lpAmount_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
    if (msg.sender == bond_) {
        _pullBondLp(lpAmount_);
    } else {
        _ensureProtocolLpOnDiamond(lpAmount_);
    }
    pairOut_ = _withdrawSinglePair(lpAmount_, recipient_ == address(0) ? msg.sender : recipient_);
    // Money route end-order: pair leave diamond → full hold-set sync (L-DETF-END-ORDER).
    _syncAllExpectedHoldReserves();

function _settleToPair(IERC20 tokenIn_, uint256 amountIn_, bool pretransferred_, uint256 deadline_)
    internal
    returns (uint256 pairAmount_)
{
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (address(tokenIn_) == address(s.pairToken)) {
        return _pullToken(tokenIn_, amountIn_, pretransferred_);
    }
    uint256 pulled_ = _pullToken(tokenIn_, amountIn_, pretransferred_);
    if (address(tokenIn_) == address(s.standardExchangeVaultShare) || _isAllowlistedTokenIn(tokenIn_)) {
        // Nested SE fund: push + pretransferred=true (L-DETF-PUSH-NESTED).
        pairAmount_ = _nestedExchangeInPush(
            IStandardExchangeIn(address(s.standardExchangeVault)),
            tokenIn_, pulled_, s.pairToken, 0, address(this), deadline_
        );
        return pairAmount_;
    }
    revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(tokenIn_, s.pairToken);

function acceptedBondTokens() external view returns (address[] memory tokens_) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    tokens_ = new address[](2);
    tokens_[0] = address(s.pairToken);
    tokens_[1] = address(s.standardExchangeVaultShare);

function createPosition(uint256 shares, uint256 lockDuration, address recipient)
    external
    onlyOwner
    nonReentrant
    returns (uint256 tokenId)
{
    // Peer path: original = effective base = shares (LP); bonus applied to both.
    tokenId = _createPositionInternal(shares, shares, lockDuration, recipient);
}

function addToDETFNFT(uint256 tokenId, uint256 shares) external onlyOwner {
    if (tokenId != DETFNFTVaultRepo._detfNFTId()) {
        revert DETFNFTRestricted(tokenId);
    }

    DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
    DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
    DETFNFTVaultRepo._addToPosition(layoutStruct, tokenId, shares);
}

/// @notice L7: effective-share weight only on ids 1 or 2. Does not change `originalShares`.
function addEffectiveSharesOnly(uint256 tokenId, uint256 shares) external onlyOwner {
    if (!_isStandingRewardNft(tokenId)) {
        revert DETFNFTRestricted(tokenId);
    }
    if (ERC721Repo._ownerOf(tokenId) == address(0)) {
        revert ReservedBondNftsNotWired();
    }
    DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
    DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
    DETFNFTVaultRepo._addEffectiveSharesOnly(layoutStruct, tokenId, shares);
}

/// @notice Debit protocol-NFT principal 1:1 (original and effective). `tokenId` must be `detfNFTId`.
function removeFromDETFNFT(uint256 tokenId, uint256 shares) external onlyOwner {
    if (tokenId != DETFNFTVaultRepo._detfNFTId()) {
        revert DETFNFTRestricted(tokenId);
    }

function transferHeldToken(IERC20 token, address to, uint256 amount) external onlyOwner nonReentrant {
    if (to == address(0) || address(token) == address(0)) revert NotAuthorized(address(0));
    if (amount == 0) revert BaseSharesZero();
    token.safeTransfer(to, amount);
}

function syncReserve(IERC20 token) public returns (bool) {
    MultiAssetBasicVaultRepo._updateReserve(token, token.balanceOf(address(this)));
    return true;
}

